function icon(name,css='') {return `<svg ${css?`class="${esc(css)}"`:''} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.monitor}</svg>`;}
function makeContext(base){
 const root=base.endsWith('/')?base.slice(0,-1):base;
 return {root,route:(slug)=>slug==='home'?root:`${root}/${slug}`,quote:(service='General inquiry')=>`${root}/contact?service=${encodeURIComponent(service)}`};
}
function button(label,url,style='primary'){return `<a class="btn btn-${esc(style)}" href="${esc(url)}">${esc(label)} ${icon('arrow','btn-arrow')}</a>`;}
function sectionHead(kicker,heading,description){return `<div class="section-head"><span class="eyebrow eyebrow-dark">${esc(kicker)}</span><h2>${esc(heading)}</h2>${description?`<p>${esc(description)}</p>`:''}</div>`;}
function priceCards(items,kind,ctx){return `<div class="pricing-grid">${items.map((p,i)=>`<article class="price-card ${p.popular?'is-popular':''}">${p.popular?'<span class="popular-tag">MOST POPULAR</span>':''}<p class="plan-type">${esc(kind)}</p><h3>${esc(p.name)}</h3><div class="plan-money"><strong>${esc(p.cost)}</strong><span>${kind==='WEBSITE PACKAGE'?'one-time':'/month'}</span></div>${p.description?`<p class="plan-intro">${esc(p.description)}</p>`:''}<ul class="tick-list">${p.features.map(t=>`<li>${icon('check')}${esc(t)}</li>`).join('')}</ul>${button('Get a Quote',ctx.quote(p.code),'dark')}</article>`).join('')}</div>`;}
function trustItem(ico,title,text){return `<div class="trust-item">${icon(ico)}<div><strong>${esc(title)}</strong><span>${esc(text)}</span></div></div>`;}
function header(ctx,current){
 const servicesDropdown=navServices.map(([name,slug])=>`<a href="${esc(ctx.route(slug))}" ${current===slug?'aria-current="page"':''}>${esc(name)}</a>`).join('');
 return `<header class="site-header"><div class="shell header-inner"><a class="brand" href="${esc(ctx.route('home'))}" aria-label="Chilton App Works home"><img src="${LOGO}" alt="Chilton App Works" width="215" height="73" decoding="async" /></a><nav class="desktop-nav" aria-label="Main navigation"><a href="${esc(ctx.route('home'))}" ${current==='home'?'aria-current="page"':''}>Home</a><details class="nav-services"><summary>Services <span aria-hidden="true">⌄</span></summary><div class="nav-dropdown">${servicesDropdown}</div></details><a href="${esc(ctx.route('pricing'))}" ${current==='pricing'?'aria-current="page"':''}>Pricing</a><a href="${esc(ctx.route('about'))}" ${current==='about'?'aria-current="page"':''}>About</a><a href="${esc(ctx.route('contact'))}" ${current==='contact'?'aria-current="page"':''}>Contact</a></nav>${button('Get a Free Quote',ctx.route('contact'),'lime')}<details class="mobile-menu"><summary aria-label="Open navigation"><span></span><span></span><span></span></summary><nav aria-label="Mobile navigation"><a href="${esc(ctx.route('home'))}">Home</a>${servicesDropdown}<a href="${esc(ctx.route('pricing'))}">Pricing</a><a href="${esc(ctx.route('about'))}">About</a><a class="mobile-contact" href="${esc(ctx.route('contact'))}">Get a Free Quote ${icon('arrow')}</a></nav></details></div></header>`;
}
function laptop(){return `<div class="device-scene" aria-label="Illustration of a Chilton App Works business website displayed on a laptop" role="img"><div class="scene-orbit orbit-one"></div><div class="scene-orbit orbit-two"></div><div class="scene-star star-one"></div><div class="scene-star star-two"></div><div class="floating-chip top-chip"><span class="live-dot"></span> Local expertise</div><div class="laptop"><div class="laptop-panel"><div class="app-topbar"><span></span><span></span><span></span><i>YOUR BUSINESS. ONLINE.</i></div><div class="laptop-brand"><img src="${LOGO}" alt="" width="440" height="246" loading="lazy" decoding="async" /></div><div class="screen-swoosh green-swoosh"></div><div class="screen-swoosh blue-swoosh"></div><div class="screen-ui"><div></div><div></div><div></div></div></div><div class="laptop-base"></div><div class="laptop-shadow"></div></div><div class="floating-chip bottom-chip">${icon('check')} Built for the real world</div></div>`;}
function hero(ctx,opts){return `<section class="hero"><div class="hero-grid shell"><div class="hero-copy"><span class="eyebrow">${esc(opts.kicker)}</span><h1>${opts.heading} <span class="accent">${opts.accent}</span></h1><p>${esc(opts.description)}</p><div class="hero-actions">${button(opts.actionLabel||'Get a Free Quote',ctx.quote(opts.service||'New project'),'lime')}${button(opts.secondaryLabel||'Explore Services',opts.secondaryUrl||ctx.route('pricing'),'outline')}</div><p class="hero-micro">${icon('check')} No hidden fees <span>·</span> Upfront, affordable pricing</p></div>${laptop()}</div></section>`;}
function cta(ctx,heading,copy,service){return `<section class="cta-section"><div class="shell cta-inner"><div><span class="eyebrow">LET'S GET STARTED</span><h2>${esc(heading)}</h2><p>${esc(copy)}</p></div><div class="cta-buttons">${button('Request a Free Quote',ctx.quote(service||'New project'),'lime')}${button('View All Services',ctx.route('home')+'#services','outline')}</div></div></section>`;}
function footer(ctx){return `<footer class="site-footer"><div class="shell footer-grid"><div><a class="footer-logo" href="${esc(ctx.route('home'))}"><img src="${LOGO}" alt="Chilton App Works" width="196" height="70" loading="lazy"/></a><p>Practical technology. Straightforward prices.<br>Local service from Chilton, Wisconsin.</p></div><div><strong>EXPLORE</strong><a href="${esc(ctx.route('home'))}">Home</a><a href="${esc(ctx.route('pricing'))}">Pricing</a><a href="${esc(ctx.route('about'))}">Our Story</a><a href="${esc(ctx.route('contact'))}">Get in Touch</a></div><div><strong>SERVICES</strong>${navServices.map(([name,slug])=>`<a href="${esc(ctx.route(slug))}">${esc(name)}</a>`).join('')}</div><div><strong>LOCAL & APPROACHABLE</strong><p>Chilton, Wisconsin</p><a href="mailto:${EMAIL}">${EMAIL}</a><p>Small-business friendly.<br>No hidden fees. No long contracts.</p></div></div><div class="shell footer-bottom"><span>© 2026 Chilton App Works LLC</span><span>Transparent pricing · Customer-owned domains and deliverables</span></div></footer>`;}
function home(ctx){return `${hero(ctx,{kicker:'CHILTON APP WORKS · CHILTON, WISCONSIN',heading:'Practical tech solutions for',accent:'your business.',description:'Professional websites, custom software, computer repair, and dependable support. Real solutions that fit your business and your budget.',actionLabel:'Start Your Project',service:'New project',secondaryLabel:'See Our Services',secondaryUrl:'#services'})}<div class="trust-bar"><div class="shell trust-grid">${trustItem('location','Locally owned','Based in Chilton, WI')}${trustItem('shield','Upfront pricing','No hidden charges')}${trustItem('tools','Computer support','Remote and local')}${trustItem('clock','Flexible plans','No required long contracts')}</div></div><section class="section services-section" id="services"><div class="shell">${sectionHead('WHAT WE DO','One local team. Five practical services.','Find what you need without digging through a wall of information. Each service has its own details and pricing.')}<div class="service-grid">${services.map(s=>`<article class="service-card"><div class="service-icon">${icon(s.icon)}</div><span class="service-tag">${esc(s.tag)}</span><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><div class="service-bottom"><strong>${esc(s.price)}</strong><a href="${esc(ctx.route(s.slug))}" aria-label="Learn more about ${esc(s.title)}">Learn More ${icon('arrow')}</a></div></article>`).join('')}</div></div></section>${cta(ctx,'Let’s make technology work for you.','Whether it’s your first website, a tricky computer problem, or software that saves time, we can help.','General inquiry')}`;}
function website(ctx){return `${hero(ctx,{kicker:'WEBSITE DESIGN',heading:'A professional website.',accent:'Without the agency price.',description:'Clean, mobile-first websites built to make your business look credible and easy to reach. Clear packages and no mystery fees.',service:'Website Design',secondaryLabel:'View Packages',secondaryUrl:'#packages'})}<section class="section page-section" id="packages"><div class="shell">${sectionHead('WEBSITE PACKAGES','Simple prices. Great first impressions.','Choose the right starting point. Every package includes responsive design and a clearly defined scope.')}${priceCards(websitePlans,'WEBSITE PACKAGE',ctx)}<p class="disclosure">Additional pages start at $99 each. Domain registration, hosting, mailbox licenses, outside providers, complex integrations, and extra work are quoted separately and approved in advance.</p></div></section><section class="section soft-section"><div class="shell two-panel"><div><span class="eyebrow eyebrow-dark">BUILT FOR REAL BUSINESSES</span><h2>Small details. Big difference.</h2><p>Every website should look polished, work on phones, and give customers a clear next step. Your business keeps its domain and the deliverables defined in your agreement.</p><a href="${esc(ctx.route('care'))}" class="inline-link">Explore optional website care ${icon('arrow')}</a></div><div class="feature-mini-grid">${[['phone','Mobile-friendly from day one'],['bolt','Fast, focused page layouts'],['globe','Basic search setup'],['shield','Your brand, your domain']].map(([i,t])=>`<div>${icon(i)}<strong>${esc(t)}</strong></div>`).join('')}</div></div></section>${cta(ctx,'Your business deserves a better website.','Tell us what you need and we’ll recommend a straightforward starting point.','Website Design')}`;}
function apps(ctx){return `${hero(ctx,{kicker:'CUSTOM APPLICATION DEVELOPMENT',heading:'Software built around',accent:'the way you work.',description:'When off-the-shelf tools don’t fit, we can create practical applications for your workflow, team, and goals.',service:'Custom Applications',secondaryLabel:'Explore Possibilities',secondaryUrl:'#capabilities'})}<section class="section page-section" id="capabilities"><div class="shell">${sectionHead('PRACTICAL SOFTWARE','Useful tools, not unnecessary complexity.','Start with a specific business problem. We’ll work out what technology actually makes sense.')}<div class="feature-grid">${appFeatures.map(([name,desc,ico])=>`<article class="feature-card"><div>${icon(ico)}</div><h3>${esc(name)}</h3><p>${esc(desc)}</p></article>`).join('')}</div></div></section><section class="section soft-section"><div class="shell">${sectionHead('HOW WE WORK','From idea to implementation.','Clear scope, milestones, and costs before building.')}<div class="steps-grid">${[['01','Discover','Understand your challenges.'],['02','Plan','Agree on features and pricing.'],['03','Build','Develop, review, and test.'],['04','Launch','Deliver and support as agreed.']].map(([n,t,d])=>`<div class="step"><span>${n}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div><p class="disclosure">Custom development, integrations, infrastructure, testing, and support are quoted based on the agreed requirements. No unapproved add-ons.</p></div></section>${cta(ctx,'Have an idea worth building?','Tell us what you want to improve. We’ll explore a practical solution and a clear quote.','Custom Applications')}`;}
function repair(ctx){return `${hero(ctx,{kicker:'COMPUTER REPAIR & TECH SUPPORT',heading:'Computer problems?',accent:'We can help.',description:'Straightforward repair and troubleshooting, including remote diagnostics and free local pickup and delivery by arrangement.',service:'Computer Repair',actionLabel:'Request Repair',secondaryLabel:'See Repair Prices',secondaryUrl:'#repairs'})}<section class="repair-promise"><div class="shell promise-inner"><div class="promise-icon">${icon('shield')}</div><div><span>OUR NO-SURPRISE PROMISE</span><h2>Can’t fix it? You only pay the diagnostic fee.</h2><p>If we attempt your agreed repair and cannot resolve the issue, we won’t charge repair labor. We explain the diagnostic fee and approve any proposed costs before work begins.</p></div></div></section><section class="section page-section" id="repairs"><div class="shell">${sectionHead('REPAIR & DIAGNOSTICS','Affordable computer help.','These are starting prices for common services. We’ll explain your total expected charge before you approve work.')}<div class="repair-grid">${repairs.map(([title,price,desc])=>`<article class="repair-card"><h3>${esc(title)}</h3><p>${esc(desc)}</p><div><strong>${esc(price)}</strong><a href="${esc(ctx.quote(title))}" aria-label="Ask about ${esc(title)}">Ask About It ${icon('arrow')}</a></div></article>`).join('')}</div></div></section><section class="section soft-section"><div class="shell">${sectionHead('SIMPLE PROCESS','No pressure. No surprises.','You stay in control of repair decisions.')}<div class="steps-grid">${[['01','Get in touch','Tell us what’s happening.'],['02','Diagnose','We find the likely cause.'],['03','Approve','You review the repair estimate.'],['04','Repair & return','We test the result and arrange return.']].map(([n,t,d])=>`<div class="step"><span>${n}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div><p class="disclosure">Free pickup and delivery is available within an agreed local service area, subject to scheduling. Remote access requires permission. Parts and third-party costs require approval before purchase.</p></div></section>${cta(ctx,'Let’s get your computer working.','Request remote diagnostics or ask about local pickup and delivery.','Computer Repair')}`;}
function care(ctx){return `${hero(ctx,{kicker:'WEBSITE CARE',heading:'A website that stays',accent:'in good hands.',description:'Optional website care for small businesses that want help with uptime monitoring, hosting coordination, and occasional updates.',service:'Website Care',secondaryLabel:'See Care Plans',secondaryUrl:'#care-plans'})}<section class="section page-section" id="care-plans"><div class="shell">${sectionHead('OPTIONAL MONTHLY SUPPORT','Care without the complicated contract.','Choose only the support your business needs, with a clear monthly allowance.')}${priceCards(carePlans,'WEBSITE CARE',ctx)}<p class="disclosure">Plans are optional and month-to-month unless otherwise agreed in writing. Provider hosting fees, domains, mailbox licenses, and work beyond a plan’s included allowance may be separate and are quoted first.</p></div></section><section class="section soft-section"><div class="shell">${sectionHead('THE IMPORTANT DETAILS','Your site. Your choices.','We help with the technical details while you maintain control of your business assets.')}<div class="feature-grid three">${[['shield','You stay in control','Your domain and agreed deliverables remain yours.'],['clock','Straightforward support','Know what your plan includes and what it doesn’t.'],['globe','No provider lock-in','Use your preferred hosting and email providers.']].map(([i,t,d])=>`<article class="feature-card"><div>${icon(i)}</div><h3>${esc(t)}</h3><p>${esc(d)}</p></article>`).join('')}</div></div></section>${cta(ctx,'Need a hand with your website?','We’ll help you choose the amount of support that fits your budget.','Website Care')}`;}
function emailPage(ctx){return `${hero(ctx,{kicker:'PROFESSIONAL BUSINESS EMAIL',heading:'A better email address.',accent:'A stronger first impression.',description:'Get professional business email at your own domain, set up to work on the devices you already use.',service:'Business Email',secondaryLabel:'See What’s Included',secondaryUrl:'#email-setup'})}<section class="section page-section" id="email-setup"><div class="shell email-layout"><div class="email-plan"><span class="eyebrow eyebrow-dark">FIRST MAILBOX SETUP</span><div class="email-price">$49 <small>starting one-time setup</small></div><h2>Simple, professional email.</h2><ul class="tick-list">${['Set up your first mailbox','Connect your business domain','Help configure email on your devices','Basic handoff and usage guidance'].map(v=>`<li>${icon('check')}${esc(v)}</li>`).join('')}</ul>${button('Ask About Email Setup',ctx.quote('Business Email'),'dark')}</div><div class="email-copy"><span class="eyebrow eyebrow-dark">YOUR BRAND, YOUR INBOX</span><h2>Look credible every time you hit send.</h2><p>A branded address helps customers know they’re dealing with a real business. We’ll guide you through your domain and provider choices without locking you into one platform.</p><div class="email-benefits">${[['mail','Your business domain','Use addresses like hello@yourbusiness.com.'],['devices','Works on your devices','Computer, phone, and browser setup guidance.'],['lock','Provider security','Use the security features of your chosen provider.']].map(([i,t,d])=>`<div>${icon(i)}<span><strong>${esc(t)}</strong><small>${esc(d)}</small></span></div>`).join('')}</div><p class="disclosure">Mailbox licenses, domain registrations and renewals, provider subscriptions, and extra mailbox work are separate, disclosed costs. Provider accounts ordinarily remain in your name.</p></div></div></section>${cta(ctx,'Let’s make your email look the part.','Get help setting up a professional address for your business.','Business Email')}`;}
function pricing(ctx){return `<section class="interior-hero"><div class="shell"><span class="eyebrow">STRAIGHTFORWARD PRICING</span><h1>No guesswork. <span>Just good value.</span></h1><p>Five services, clear starting prices, and no hidden charges. Select what you need for complete details.</p></div></section><section class="section page-section"><div class="shell">${sectionHead('FIND YOUR FIT','Explore pricing by service.','We make it simple to start small and add only what you need.')}<div class="pricing-list">${services.map(s=>`<a href="${esc(ctx.route(s.slug))}" class="pricing-list-row"><span class="pricing-icon">${icon(s.icon)}</span><span><strong>${esc(s.title)}</strong><small>${esc(s.description)}</small></span><b>${esc(s.price)}</b>${icon('arrow')}</a>`).join('')}</div><p class="disclosure">Starting prices are for defined scopes. Parts, external provider fees, upgrades, domains, and work outside scope are disclosed and approved before charging.</p></div></section>${cta(ctx,'Want to know exactly what it’ll cost?','Tell us what you have in mind. We’ll provide an upfront quote.','Pricing Question')}`;}
function about(ctx){return `<section class="interior-hero"><div class="shell"><span class="eyebrow">BASED IN CHILTON, WISCONSIN</span><h1>Local roots. <span>Practical technology.</span></h1><p>Chilton App Works LLC brings affordable websites, custom software, and computer help within reach for small businesses and local residents.</p></div></section><section class="section page-section"><div class="shell about-layout"><div><span class="eyebrow eyebrow-dark">WHY WE EXIST</span><h2>Good technology shouldn’t come with a giant price tag.</h2><p>Whether you’re opening a small business, updating a website that’s fallen behind, or getting a computer working again, you deserve clear answers and a fair price.</p><p>We keep the process straightforward and build solutions around what you actually need.</p>${button('Let’s Talk',ctx.quote('About Chilton App Works'),'dark')}</div><div class="values-panel">${[['shield','Transparent','No hidden fees or surprise charges.'],['location','Local','Proudly based in Chilton, Wisconsin.'],['globe','Independent','Freedom to choose your own providers.']].map(([i,t,d])=>`<div>${icon(i)}<div><strong>${esc(t)}</strong><p>${esc(d)}</p></div></div>`).join('')}</div></div></section>${cta(ctx,'Let’s build something useful.','From your first website to a unique business app, we’re ready to listen.','New project')}`;}
function contact(ctx){return `<section class="interior-hero"><div class="shell"><span class="eyebrow">LET’S TALK</span><h1>Tell us what you need. <span>We’ll go from there.</span></h1><p>No sales maze, no surprise fees. Just a straightforward conversation about your project or computer issue.</p></div></section><section class="section page-section"><div class="shell contact-layout"><div class="contact-copy"><span class="eyebrow eyebrow-dark">GET IN TOUCH</span><h2>Big project or quick question?</h2><p>Tell us a little about your business or computer problem. We’ll discuss practical options and clear starting prices.</p><div class="contact-detail">${icon('location')}<span><strong>Local to Chilton, Wisconsin</strong><small>Remote support and free local computer pickup by arrangement.</small></span></div><div class="contact-detail">${icon('mail')}<span><strong>Email us directly</strong><a href="mailto:${EMAIL}">${EMAIL}</a></span></div><div class="contact-detail">${icon('shield')}<span><strong>Upfront pricing</strong><small>No hidden charges or required long contracts.</small></span></div></div><form class="contact-form" id="chilton-inquiry"><h2>Request a Free Quote</h2><label for="inquiry-name">Your name <span>*</span></label><input id="inquiry-name" name="name" autocomplete="name" required placeholder="Your name" /><label for="inquiry-email">Email address <span>*</span></label><input id="inquiry-email" name="email" type="email" autocomplete="email" required placeholder="you@example.com" /><label for="inquiry-business">Business name (optional)</label><input id="inquiry-business" name="business" autocomplete="organization" placeholder="Your business" /><label for="inquiry-service">What can we help with?</label><select id="inquiry-service" name="service">${['Website Design','One-Page Starter website','Small Business website','Business Plus website','Custom Applications','Computer Repair','Website Care','Basic Hosting','Managed Care','Premium Care','Business Email','Other Question'].map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('')}</select><label for="inquiry-message">Tell us a little about it</label><textarea id="inquiry-message" name="message" rows="5" placeholder="What would you like help with?"></textarea><button type="submit" class="btn btn-dark">Prepare My Email ${icon('arrow','btn-arrow')}</button><p class="form-disclosure">This opens your email app with a prepared message for you to review and send. It does not automatically send or store your information.</p></form></div></section>`;}

function pageHTML(slug,ctx){switch(slug){case'website-design':return website(ctx);case'apps':case'work':return apps(ctx);case'repair':return repair(ctx);case'care':return care(ctx);case'email':return emailPage(ctx);case'pricing':return pricing(ctx);case'about':return about(ctx);case'contact':return contact(ctx);case'services':return home(ctx);default:return home(ctx)}}

