const inlineJs=`(function(){
  const f=document.getElementById('chilton-inquiry');
  if(f){
    const params=new URLSearchParams(location.search);let service=params.get('service');
    if(service){const select=f.querySelector('select[name=service]');if(select){let match=[...select.options].find(o=>o.value.toLowerCase()===service.toLowerCase());if(!match){const opt=document.createElement('option');opt.value=service;opt.textContent=service;select.appendChild(opt);match=opt;}select.value=match.value;}}
    f.addEventListener('submit',function(e){e.preventDefault();if(!f.reportValidity())return;const v=new FormData(f);const subject='Chilton App Works | '+(v.get('service')||'New inquiry');const body=['Name: '+v.get('name'),'Business: '+(v.get('business')||'Not provided'),'Reply email: '+v.get('email'),'Service: '+v.get('service'),'','Project details:',v.get('message')||'Not provided'].join('\\n');location.href='mailto:Geoffrey@86chaos.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);});
  }
  document.addEventListener('keydown',function(e){if(e.key==='Escape'){document.querySelectorAll('details[open]').forEach(d=>d.removeAttribute('open'));}});
})();`;

export function renderChiltonPage(page='home',base='/chilton-app-works-neon') {
  const normalized=['home','website-design','apps','repair','care','email','pricing','about','contact','services','work'].includes(page)?page:'home';
  const ctx=makeContext(base);
  const headings={home:'Small Business Websites, Computer Repair & Custom Apps','website-design':'Website Design','apps':'Custom Application Development','repair':'Computer Repair & Remote Diagnostics','care':'Website Care & Maintenance','email':'Business Email Setup',pricing:'Transparent Pricing',about:'About Us',contact:'Contact Us',services:'Our Services',work:'Custom Applications'};
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#052954"><meta name="robots" content="noindex,nofollow"><title>${esc(headings[normalized]||headings.home)} | Chilton App Works</title><meta name="description" content="Chilton App Works in Chilton, Wisconsin: affordable websites, custom applications, remote computer diagnostics, local computer repair, website care, and business email. Upfront prices, no hidden fees."><style>${CSS}</style></head><body>${header(ctx,normalized)}<main id="main-content">${pageHTML(normalized,ctx)}</main>${footer(ctx)}<script>${inlineJs}</script></body></html>`;
}